namespace Symfony\AI\Bc;

/**
 * Renders the public API of a package as one sorted line per symbol, made for reading diffs.
 *
 * @author Christopher Hertel <mail@christopher-hertel.de>
 */
final class SnapshotRenderer
{
    public function render(Api $api, Package $package): string
    {
        $classes = array_filter($api->classes, static fn (ClassApi $class): bool => $class->package === $package->name);
        usort($classes, static fn (ClassApi $a, ClassApi $b): int => strcmp($a->name, $b->name));

        $lines = [];
        foreach ($classes as $class) {
            array_push($lines, ...$this->renderClass($class));
        }

        $header = \sprintf("# Public API of %s, generated by \"php .github/bc/bc.php dump\". Do not edit.\n", $package->name);

        return $header.implode("\n", $lines).([] !== $lines ? "\n" : '');
    }

    public static function signature(MethodApi $method): string
    {
        $modifiers = array_filter([
            $method->final ? 'final' : null,
            $method->abstract ? 'abstract' : null,
            $method->visibility,
            $method->static ? 'static' : null,
        ]);

        $parameters = array_map(static function (ParameterApi $parameter): string {
            return ltrim(\sprintf(
                '%s %s%s$%s%s',
                $parameter->type ?? '',
                $parameter->byRef ? '&' : '',
                $parameter->variadic ? '...' : '',
                $parameter->name,
                null !== $parameter->default ? ' = '.$parameter->default : '',
            ));
        }, $method->parameters);

        foreach ($method->virtualParameters as $name => $type) {
            $parameters[] = \sprintf('/* %s$%s */', null !== $type ? $type.' ' : '', $name);
        }

        return \sprintf(
            '%s function %s(%s)%s',
            implode(' ', $modifiers),
            $method->name,
            implode(', ', $parameters),
            null !== $method->returnType ? ': '.$method->returnType : '',
        );
    }

    public static function isVisible(string $visibility, bool $extensible, bool $trait): bool
    {
        return 'public' === $visibility || $trait || ('protected' === $visibility && $extensible);
    }

    /**
     * @return list<string>
     */
    private function renderClass(ClassApi $class): array
    {
        if ($class->internal) {
            return [$class->name.': @internal '.$class->kind];
        }
        if ($class->experimental) {
            return [$class->name.': @experimental '.$class->kind];
        }

        $modifiers = array_filter([
            $class->final ? 'final' : null,
            $class->abstract ? 'abstract' : null,
            $class->readonly ? 'readonly' : null,
            $class->kind,
        ]);
        $line = $class->name.': '.implode(' ', $modifiers);
        if (null !== $class->parent) {
            $line .= ' extends '.$class->parent;
        }
        if ([] !== $class->interfaces) {
            $line .= ('interface' === $class->kind ? ' extends ' : ' implements ').implode(', ', $class->interfaces);
        }
        if ([] !== $class->traits) {
            $line .= ' uses '.implode(', ', $class->traits);
        }
        $line .= self::tags($class->finalTag, $class->deprecated).($class->announcedInternal ? ' @internal since' : '');

        $lines = [$line];
        $extensible = $class->isExtensible();
        $trait = 'trait' === $class->kind;

        foreach ($class->cases as $case) {
            $lines[] = $class->name.'::'.$case.': case';
        }

        foreach ($class->constants as $constant) {
            if ($constant->internal || !self::isVisible($constant->visibility, $extensible, $trait)) {
                continue;
            }
            $lines[] = \sprintf('%s::%s: %s%s const%s', $class->name, $constant->name, $constant->final ? 'final ' : '', $constant->visibility, self::tags(null, $constant->deprecated));
        }

        foreach ($class->properties as $property) {
            if ($property->internal || !self::isVisible($property->visibility, $extensible, $trait)) {
                continue;
            }
            $modifiers = array_filter([$property->visibility, $property->static ? 'static' : null, $property->readonly ? 'readonly' : null, $property->type]);
            $lines[] = \sprintf('%s::$%s: %s%s', $class->name, $property->name, implode(' ', $modifiers), self::tags(null, $property->deprecated));
        }

        foreach ($class->methodTags as $signature) {
            $lines[] = \sprintf('%s::%s: @method %s', $class->name, substr($signature, 0, (int) strpos($signature, '(')).'()', $signature);
        }

        foreach ($class->methods as $method) {
            if ($method->internal || !self::isVisible($method->visibility, $extensible, $trait)) {
                continue;
            }
            $lines[] = $class->name.'::'.$method->name.'(): '.self::signature($method).self::tags($method->finalTag, $method->deprecated).($method->announcedInternal ? ' @internal since' : '');
        }

        return $lines;
    }

    private static function tags(?string $finalTag, ?string $deprecated): string
    {
        $tags = '';
        if (null !== $finalTag) {
            $tags .= ' @final'.('' !== $finalTag ? ' '.self::since($finalTag) : '');
        }
        if (null !== $deprecated) {
            $tags .= ' @deprecated'.('' !== self::since($deprecated) ? ' '.self::since($deprecated) : '');
        }

        return $tags;
    }

    private static function since(string $description): string
    {
        return 1 === preg_match('/^since\s+[^,.]*?\d+\.\d+/', $description, $match) ? $match[0] : '';
    }
}
